import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { getAllUsers, banUser } from '../services/api';

export default function ManageUsers() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [msg, setMsg] = useState('');
  const [search, setSearch] = useState('');
  const [roleFilter, setRoleFilter] = useState('ALL');

  useEffect(() => { load(); }, []);

  const load = async () => {
    try { const r = await getAllUsers(); setUsers(r.data); }
    catch {} finally { setLoading(false); }
  };

  const toggleBan = async (u) => {
    const action = u.banned ? 'Unban' : 'Ban';
    if (!window.confirm(`${action} ${u.name}?`)) return;
    try {
      await banUser(u.id, { banned: !u.banned });
      setMsg(`${u.name} ${u.banned ? 'unbanned' : 'banned'}.`);
      load();
    } catch {}
  };

  const filtered = users.filter(u => {
    const matchRole = roleFilter === 'ALL' || u.role === roleFilter;
    const matchSearch = !search || u.name?.toLowerCase().includes(search.toLowerCase()) ||
      u.email?.toLowerCase().includes(search.toLowerCase());
    return matchRole && matchSearch;
  });

  return (
    <>
      <Navbar />
      <div className="page">
        <div className="page-header">
          <h1 className="page-title">Manage Users</h1>
          <div style={{ display: 'flex', gap: '10px' }}>
            <input className="form-control" placeholder="Search by name or email…"
              value={search} onChange={e => setSearch(e.target.value)} style={{ width: '240px' }} />
            <select className="form-control" value={roleFilter}
              onChange={e => setRoleFilter(e.target.value)} style={{ width: '130px' }}>
              <option value="ALL">All Roles</option>
              <option value="STUDENT">Students</option>
              <option value="ADMIN">Admins</option>
            </select>
          </div>
        </div>
        {msg && <div className="alert alert-success">{msg}</div>}

        {/* Stats */}
        <div style={{ display:'flex', gap:'1rem', marginBottom:'1.5rem', flexWrap:'wrap' }}>
          {[
            { label:'Total', value: users.length, color:'var(--accent2)' },
            { label:'Students', value: users.filter(u=>u.role==='STUDENT').length, color:'var(--blue)' },
            { label:'Admins', value: users.filter(u=>u.role==='ADMIN').length, color:'var(--green)' },
            { label:'Banned', value: users.filter(u=>u.banned).length, color:'var(--red)' },
          ].map(s => (
            <div key={s.label} className="stat-card" style={{ flex:'1', minWidth:'110px', padding:'0.9rem' }}>
              <div className="num" style={{ color:s.color, fontSize:'1.6rem' }}>{s.value}</div>
              <div className="lbl">{s.label}</div>
            </div>
          ))}
        </div>

        {loading ? <div className="skeleton" style={{ height:'300px', borderRadius:'14px' }} /> : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr><th>#</th><th>Name</th><th>Email</th><th>Role</th><th>Profile</th><th>Joined</th><th>Status</th><th>Action</th></tr>
              </thead>
              <tbody>
                {filtered.map((u, i) => (
                  <tr key={u.id}>
                    <td style={{ color:'var(--text3)' }}>{i+1}</td>
                    <td>
                      <div style={{ display:'flex', alignItems:'center', gap:'8px' }}>
                        <div style={{ width:'32px', height:'32px', borderRadius:'50%', background:'var(--surface2)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:'0.9rem', fontWeight:'600', color:'var(--accent2)', flexShrink:0 }}>
                          {u.name?.charAt(0)?.toUpperCase()}
                        </div>
                        <span style={{ fontWeight:500 }}>{u.name}</span>
                      </div>
                    </td>
                    <td style={{ fontSize:'0.83rem', color:'var(--text2)' }}>{u.email}</td>
                    <td>
                      <span className={`badge ${u.role==='ADMIN' ? 'badge-shortlisted' : 'badge-applied'}`}>
                        {u.role}
                      </span>
                    </td>
                    <td>
                      <div style={{ display:'flex', alignItems:'center', gap:'6px' }}>
                        <div style={{ width:'60px', height:'5px', background:'var(--surface2)', borderRadius:'3px', overflow:'hidden' }}>
                          <div style={{ height:'100%', background:'var(--accent)', width:`${u.profileCompletion||0}%` }} />
                        </div>
                        <span style={{ fontSize:'0.75rem', color:'var(--text3)' }}>{u.profileCompletion||0}%</span>
                      </div>
                    </td>
                    <td style={{ fontSize:'0.8rem', color:'var(--text3)', whiteSpace:'nowrap' }}>
                      {u.createdAt ? new Date(u.createdAt).toLocaleDateString() : '—'}
                    </td>
                    <td>
                      {u.banned
                        ? <span className="badge badge-rejected">Banned</span>
                        : u.verified
                          ? <span className="badge badge-accepted">Active</span>
                          : <span className="badge badge-under_review">Unverified</span>
                      }
                    </td>
                    <td>
                      <button
                        className={`btn btn-xs ${u.banned ? 'btn-success' : 'btn-danger'}`}
                        onClick={() => toggleBan(u)}>
                        {u.banned ? 'Unban' : 'Ban'}
                      </button>
                    </td>
                  </tr>
                ))}
                {filtered.length === 0 && (
                  <tr><td colSpan={8} style={{ textAlign:'center', color:'var(--text3)', padding:'2rem' }}>No users found.</td></tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </>
  );
}
